arduino.setup:
Serial.begin(9600);
pinMode(${2}, INPUT);
pinMode(13, OUTPUT);
Serial.println("Slide Switch Ready");

arduino.loop:
bool switchState_${COMP_SUFFIX} = digitalRead(${2});
if (switchState_${COMP_SUFFIX} != lastSwitchState_${COMP_SUFFIX}) {
  Serial.print("Switch: ");
  Serial.println(switchState_${COMP_SUFFIX} ? "ON" : "OFF");
  digitalWrite(13, switchState_${COMP_SUFFIX} ? HIGH : LOW);
  lastSwitchState_${COMP_SUFFIX} = switchState_${COMP_SUFFIX};
}
delay(50);
